import 'dart:io';
import 'dart:typed_data';

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:path_provider/path_provider.dart';
import 'package:video_thumbnail/video_thumbnail.dart';

/// Builds a sharp, ability-specific poster from the actual bundled MP4.
/// Generated bytes are cached for this app session; the source MP4 is copied
/// to the temporary directory only once.
class VideoAssetThumbnail extends StatelessWidget {
  const VideoAssetThumbnail({
    super.key,
    required this.videoAsset,
    required this.fallbackAsset,
    this.timeMs = 1800,
    this.fit = BoxFit.cover,
  });

  final String videoAsset;
  final String fallbackAsset;
  final int timeMs;
  final BoxFit fit;

  static final Map<String, Future<Uint8List?>> _cache = {};

  Future<Uint8List?> _thumbnail() {
    final key = '$videoAsset@$timeMs';
    return _cache.putIfAbsent(key, () => _generate());
  }

  Future<Uint8List?> _generate() async {
    try {
      final data = await rootBundle.load(videoAsset);
      final bytes = data.buffer.asUint8List(
        data.offsetInBytes,
        data.lengthInBytes,
      );
      final temporaryDirectory = await getTemporaryDirectory();
      final sourceDirectory = Directory(
        '${temporaryDirectory.path}/viper_preview_sources',
      );
      await sourceDirectory.create(recursive: true);

      final fileName = videoAsset.split('/').last;
      final sourceFile = File('${sourceDirectory.path}/$fileName');
      if (!await sourceFile.exists() ||
          await sourceFile.length() != bytes.length) {
        await sourceFile.writeAsBytes(bytes, flush: true);
      }

      return VideoThumbnail.thumbnailData(
        video: sourceFile.path,
        imageFormat: ImageFormat.JPEG,
        maxWidth: 960,
        timeMs: timeMs,
        quality: 92,
      );
    } catch (_) {
      // Keep the dossier usable if thumbnail extraction is unavailable.
      return null;
    }
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<Uint8List?>(
      future: _thumbnail(),
      builder: (context, snapshot) {
        final bytes = snapshot.data;
        if (bytes != null && bytes.isNotEmpty) {
          return Image.memory(
            bytes,
            fit: fit,
            gaplessPlayback: true,
            filterQuality: FilterQuality.high,
          );
        }
        return Image.asset(
          fallbackAsset,
          fit: fit,
          filterQuality: FilterQuality.high,
        );
      },
    );
  }
}
